VK_Y=121
VK_N=110
VK_SPACE=32
VK_RETURN=13

SDLK_UP=273
SDLK_DOWN=274
SDLK_LEFT=276
SDLK_RIGHT=275

if CONFIG.Rotate==0 then
VK_UP=SDLK_UP;
VK_DOWN=SDLK_DOWN;
VK_LEFT=SDLK_LEFT;
